// YouTube Comment Bulk Deletion via My Activity
// Generated by YouTube Takeout Manager
// __COMMENT_COUNT__ comment(s) queued for deletion

(async function() {
  const commentIds = __COMMENT_IDS__;
  const delayMs = 1000;
  const results = { succeeded: [], failed: [] };

  // --- Dynamic rpcid discovery ---
  async function discoverDeleteRpcId() {
    const bundles = performance.getEntriesByType('resource')
      .filter(r => r.name.includes('boq-footprints') && r.name.includes('/js/'))
      .map(r => r.name);
    const uniqueBundles = [...new Set(bundles)];
    const SERVICE_PATH = '/MyactivityService.Delete';

    for (const url of uniqueBundles) {
      try {
        const res = await fetch(url);
        const text = await res.text();
        const serviceIdx = text.indexOf(SERVICE_PATH);
        if (serviceIdx === -1) continue;

        let pos = serviceIdx - 2;
        while (pos >= 0 && text[pos] !== '"') pos--;
        const closingQuote = pos;
        pos--;
        while (pos >= 0 && text[pos] !== '"') pos--;
        const rpcid = text.substring(pos + 1, closingQuote);

        if (/^[A-Za-z0-9]{3,12}$/.test(rpcid)) return rpcid;
      } catch(e) {}
    }
    return null;
  }

  // --- Auto-detect build-dependent values from WIZ_global_data ---
  const wiz = WIZ_global_data;
  const wizEntries = Object.entries(wiz);

  const at = wizEntries.find(([k, v]) => typeof v === 'string' && /^[A-Za-z0-9_-]+:\d+$/.test(v))?.[1];
  const bl = wizEntries.find(([k, v]) => typeof v === 'string' && v.startsWith('boq_'))?.[1];
  const fsid = wizEntries.find(([k, v]) => typeof v === 'string' && /^-\d{15,}$/.test(v))?.[1];

  if (!at) throw new Error('Could not find XSRF token');
  if (!bl) throw new Error('Could not find build label');

  const rpcid = await discoverDeleteRpcId();
  if (!rpcid) throw new Error('Could not discover delete rpcid from bundles');

  console.log(`Discovered rpcid: ${rpcid}, build label: ${bl}`);

  // --- Core delete function ---
  function buildDeleteUrl() {
    const params = new URLSearchParams({
      'rpcids': rpcid,
      'source-path': '/page',
      'bl': bl,
      'hl': 'en',
      'soc-app': '712',
      'soc-platform': '1',
      'soc-device': '1',
      '_reqid': Math.floor(Math.random() * 900000 + 100000),
      'rt': 'c'
    });
    if (fsid) params.set('f.sid', fsid);
    return `/_/FootprintsMyactivityUi/data/batchexecute?${params}`;
  }

  async function deleteComment(commentId) {
    const freq = JSON.stringify([[
      [rpcid, JSON.stringify([[null, null, ["youtube_comments"]], [commentId]]), null, "generic"]
    ]]);
    const body = new URLSearchParams({ 'f.req': freq, 'at': at });

    return fetch(buildDeleteUrl(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
      body: body.toString(),
      credentials: 'same-origin'
    });
  }

  // --- Bulk delete with progress and results collection ---
  console.log(`Starting deletion of ${commentIds.length} comments...`);

  for (let i = 0; i < commentIds.length; i++) {
    const id = commentIds[i];
    try {
      const response = await deleteComment(id);
      if (response.ok) {
        results.succeeded.push(id);
        console.log(`[${i + 1}/${commentIds.length}] Deleted ${id}`);
      } else {
        results.failed.push({ id, error: `HTTP ${response.status}` });
        console.error(`[${i + 1}/${commentIds.length}] FAILED ${id}: HTTP ${response.status}`);
      }
    } catch (e) {
      results.failed.push({ id, error: e.message || String(e) });
      console.error(`[${i + 1}/${commentIds.length}] FAILED ${id}: ${e.message || e}`);
    }
    if (i < commentIds.length - 1) {
      await new Promise(r => setTimeout(r, delayMs));
    }
  }

  console.log(`\nDone! ${results.succeeded.length} succeeded, ${results.failed.length} failed`);
  const resultsJson = JSON.stringify(results);

  // Create a clickable "Copy Results" button in the console
  const btnStyle = 'font-size:14px;padding:6px 16px;background:#1a73e8;color:#fff;border:none;border-radius:4px;cursor:pointer;';
  const btn = document.createElement('button');
  btn.textContent = 'Copy Results to Clipboard';
  btn.setAttribute('style', btnStyle);
  btn.onclick = async () => {
    try {
      await navigator.clipboard.writeText(resultsJson);
      btn.textContent = 'Copied!';
      btn.style.background = '#188038';
    } catch (e) {
      // Fallback: select from a temporary textarea
      const ta = document.createElement('textarea');
      ta.value = resultsJson;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
      btn.textContent = 'Copied!';
      btn.style.background = '#188038';
    }
  };
  document.body.appendChild(btn);
  btn.style.position = 'fixed';
  btn.style.bottom = '20px';
  btn.style.right = '20px';
  btn.style.zIndex = '999999';
  console.log('%c👆 Click the blue button in the bottom-right corner to copy results, then paste them back into the app.', 'font-size:13px;font-weight:bold;');
})();
